{
  "name": "@skillhub/cli",
  "version": "1.0.0",
  "description": "Universal Skill Manager CLI for AI Agents (Claude Code, OpenCode, Cursor, Windsurf)",
  "bin": {
    "skillhub": "./bin/skillhub.js"
  },
  "type": "module",
  "dependencies": {
    "@skillhub/core": "1.0.0"
  },
  "license": "Apache-2.0"
}

{
  "name": "@skillhub/core",
  "version": "1.0.0",
  "description": "Core engine for SkillHub: Universal Skill Spec parser, agent adapters, security scanner, and dependency resolver.",
  "main": "./dist/index.js",
  "type": "module",
  "scripts": {
    "build": "tsc"
  },
  "license": "Apache-2.0"
}

{
  "name": "@skillhub/registry-api",
  "version": "1.0.0",
  "description": "SkillHub Global Package Registry Server and Security Audit API",
  "main": "./src/server.js",
  "type": "module",
  "dependencies": {
    "@skillhub/core": "1.0.0"
  },
  "scripts": {
    "start": "node src/server.js"
  },
  "license": "Apache-2.0"
}
